import Foundation

enum AppLanguage: String, CaseIterable {
    case auto
    case traditionalChinese = "zh-Hant"
    case english = "en"
    case japanese = "ja"
    case korean = "ko"

    static var resolved: AppLanguage {
        resolve(stored: UserDefaults.standard.string(forKey: "interfaceLanguage"), preferredLanguages: Locale.preferredLanguages)
    }

    static func resolve(stored: String?, preferredLanguages: [String]) -> AppLanguage {
        if let chosen = AppLanguage(rawValue: stored ?? "auto"), chosen != .auto {
            return chosen
        }
        let preferred = preferredLanguages.first?.lowercased() ?? "en"
        if preferred.hasPrefix("zh") { return .traditionalChinese }
        if preferred.hasPrefix("ja") { return .japanese }
        if preferred.hasPrefix("ko") { return .korean }
        return .english
    }
}

