        "voiceCallThinking": [.traditionalChinese: "Miku 正在想怎麼回答…", .english: "Miku is thinking…", .japanese: "ミクが考え中…", .korean: "미쿠가 생각 중…"],
        "voiceCallSpeaking": [.traditionalChinese: "Miku 正在說話…", .english: "Miku is speaking…", .japanese: "ミクが話しているよ…", .korean: "미쿠가 말하는 중…"],
        "voiceCallThinkingListening": [.traditionalChinese: "Miku 正在想，你可以繼續說…", .english: "Miku is thinking. You can keep talking…", .japanese: "ミクが考え中。そのまま話してね…", .korean: "미쿠가 생각 중이야. 계속 말해도 돼…"],
        "voiceCallSpeakingListening": [.traditionalChinese: "Miku 正在說話，你可以直接插話…", .english: "Miku is speaking. You can interrupt by talking…", .japanese: "ミクが話しているよ。途中でも話しかけてね…", .korean: "미쿠가 말하고 있어. 바로 끼어들어도 돼…"],
        "voiceCallReplyInterrupted": [.traditionalChinese: "（回覆已中斷）", .english: "(Reply interrupted)", .japanese: "（返事は途中で中断されました）", .korean: "(답변이 중단됐어요)"],
        "voiceCallEchoCancellationUnavailable": [.traditionalChinese: "目前音訊裝置無法啟用通話回音消除，請更換輸入或輸出裝置後再試。", .english: "Echo cancellation is unavailable on this audio setup. Try another input or output device.", .japanese: "この音声デバイスでは通話のエコー除去を有効にできません。入力または出力デバイスを変更して再試行してください。", .korean: "현재 오디오 장치에서 통화 에코 제거를 사용할 수 없어요. 입력 또는 출력 장치를 바꾼 뒤 다시 시도해 주세요."],
        "voiceCallPaused": [.traditionalChinese: "麥克風已靜音", .english: "Microphone muted", .japanese: "マイクはミュート中", .korean: "마이크가 꺼져 있어요"],
        "voiceCallFailed": [.traditionalChinese: "通話已暫停", .english: "Conversation paused", .japanese: "通話を一時停止しました", .korean: "통화가 일시 중지됐어요"],
        "voiceCallSubtitlePlaceholder": [.traditionalChinese: "你說的話會顯示在這裡。", .english: "Your words will appear here.", .japanese: "話した言葉がここに表示されます。", .korean: "말한 내용이 여기에 표시돼요."],
        "voiceCallPrivacy": [.traditionalChinese: "本機辨識 · 不儲存音訊", .english: "On-device · Audio not saved", .japanese: "端末内で認識・録音は保存しません", .korean: "기기 내 인식 · 음성 저장 안 함"],
        "voiceCallNeedsSpeech": [.traditionalChinese: "請先在設定啟用朗讀，再開始語音通話。", .english: "Turn on reading aloud in Settings before starting a voice conversation.", .japanese: "設定で読み上げをオンにしてから音声通話を始めてください。", .korean: "설정에서 답장 읽어 주기를 켠 뒤 음성 대화를 시작해 주세요."],
        "voiceCallNeedsModel": [.traditionalChinese: "請先在語音設定選擇你自己的本機 TTS 模型。", .english: "Select your own local TTS model in voice settings first.", .japanese: "先に音声設定で自分のローカルTTSモデルを選んでください。", .korean: "먼저 음성 설정에서 본인의 로컬 TTS 모델을 선택해 주세요."],
        "voiceCallNeedsUnmute": [.traditionalChinese: "Miku 目前已靜音，請先取消靜音再通話。", .english: "Miku is muted. Unmute her before starting a conversation.", .japanese: "ミクはミュート中です。解除してから通話を始めてください。", .korean: "미쿠가 음소거 상태예요. 음소거를 해제한 뒤 통화해 주세요."],
        "voiceCallMicrophoneDenied": [.traditionalChinese: "請在「系統設定 → 隱私權與安全性 → 麥克風」允許 Miku Desktop。", .english: "Allow Miku Desktop in System Settings → Privacy & Security → Microphone.", .japanese: "「システム設定 → プライバシーとセキュリティ → マイク」でMiku Desktopを許可してください。", .korean: "시스템 설정 → 개인정보 보호 및 보안 → 마이크에서 Miku Desktop을 허용해 주세요."],
        "voiceCallSpeechDenied": [.traditionalChinese: "請在「系統設定 → 隱私權與安全性 → 語音辨識」允許 Miku Desktop。", .english: "Allow Miku Desktop in System Settings → Privacy & Security → Speech Recognition.", .japanese: "「システム設定 → プライバシーとセキュリティ → 音声認識」でMiku Desktopを許可してください。", .korean: "시스템 설정 → 개인정보 보호 및 보안 → 음성 인식에서 Miku Desktop을 허용해 주세요."],
        "voiceCallOnDeviceUnavailable": [.traditionalChinese: "這部 Mac 的本機辨識尚未可用。請先確認所選語言的離線資源，再重試。", .english: "On-device recognition is not ready. Check the offline resources for your selected language and retry.", .japanese: "端末内認識がまだ利用できません。選択した言語のオフラインデータを確認して再試行してください。", .korean: "기기 내 인식을 아직 사용할 수 없어요. 선택한 언어의 오프라인 데이터를 확인하고 다시 시도해 주세요."],
        "voiceCallInputUnavailable": [.traditionalChinese: "找不到可用的麥克風。請檢查輸入裝置後再試一次。", .english: "No microphone is available. Check your input device and try again.", .japanese: "使えるマイクがありません。入力装置を確認してから再試行してください。", .korean: "사용 가능한 마이크가 없어요. 입력 장치를 확인한 뒤 다시 시도해 주세요."],
        "voiceCallRecognitionFailed": [.traditionalChinese: "這次沒能辨識語音，請重新開始通話。", .english: "Speech recognition stopped. Start the conversation again.", .japanese: "音声を認識できませんでした。もう一度通話を始めてください。", .korean: "음성 인식이 중지됐어요. 통화를 다시 시작해 주세요."],
        "voiceCallReplyFailed": [.traditionalChinese: "這次語音回覆未完成。請檢查本機 AI 與朗讀狀態後再試一次。", .english: "The spoken reply did not finish. Check your local AI and speech status, then try again.", .japanese: "音声の返事を完了できませんでした。ローカルAIと読み上げの状態を確認して再試行してください。", .korean: "음성 답변을 완료하지 못했어요. 로컬 AI와 읽어 주기 상태를 확인한 뒤 다시 시도해 주세요."],

        // Errors
        "replyFailed": [.traditionalChinese: "暫時未能取得回覆，請重試。", .english: "Could not get a reply. Please try again.", .japanese: "返信を取得できませんでした。もう一度お試しください。", .korean: "답장을 받지 못했어요. 다시 시도해 주세요."],
        "errorConnect": [.traditionalChinese: "連不上本機 AI（%@）。請確認 oMLX 已啟動。", .english: "Can't reach the local AI at %@. Make sure oMLX is running.", .japanese: "ローカル AI（%@）に接続できません。oMLX が起動しているか確認してください。", .korean: "로컬 AI(%@)에 연결할 수 없어요. oMLX가 실행 중인지 확인해 주세요."],
        "errorTimeout": [.traditionalChinese: "本機 AI 回覆逾時，模型可能仍在載入。", .english: "The local AI timed out — the model may still be loading.", .japanese: "ローカル AI の応答がタイムアウトしました。モデルを読み込み中かもしれません。", .korean: "로컬 AI 응답 시간이 초과되었어요. 모델을 불러오는 중일 수 있어요."],
        "errorAuth": [.traditionalChinese: "本機 AI 拒絕了請求（API key 不符）。", .english: "The local AI rejected the request (API key mismatch).", .japanese: "ローカル AI にリクエストを拒否されました（API キー不一致）。", .korean: "로컬 AI가 요청을 거부했어요(API 키 불일치)."],
        "errorNotFound": [.traditionalChinese: "找不到模型「%@」，請在設定中檢查模型名稱。", .english: "Model “%@” was not found. Check the model name in Settings.", .japanese: "モデル「%@」が見つかりません。設定でモデル名を確認してください。", .korean: "모델 “%@”을 찾을 수 없어요. 설정에서 모델 이름을 확인해 주세요."],
        "errorHTTP": [.traditionalChinese: "本機 AI 回傳錯誤（HTTP %@）。", .english: "The local AI returned an error (HTTP %@).", .japanese: "ローカル AI がエラーを返しました（HTTP %@）。", .korean: "로컬 AI에서 오류를 반환했어요(HTTP %@)."],
        "errorEndpoint": [.traditionalChinese: "端點必須是本機位址（127.0.0.1、localhost 或 ::1）。", .english: "The endpoint must be a loopback address (127.0.0.1, localhost or ::1).", .japanese: "エンドポイントはループバックアドレス（127.0.0.1、localhost、::1）にしてください。", .korean: "엔드포인트는 루프백 주소(127.0.0.1, localhost 또는 ::1)여야 해요."],
        "errorReply": [.traditionalChinese: "Miku 一時語塞了（模型回覆格式不正確），請再試一次。", .english: "Miku got tongue-tied (the model's reply was malformed). Please try again.", .japanese: "ミクが言葉に詰まっちゃった（返答の形式が不正）。もう一度試してね。", .korean: "미쿠가 잠시 말문이 막혔어요(모델 응답 형식 오류). 다시 시도해 주세요."],
        "errorUnknown": [.traditionalChinese: "暫時未能取得回覆：%@", .english: "Could not get a reply: %@", .japanese: "返信を取得できませんでした：%@", .korean: "답장을 받지 못했어요: %@"],

