        "awareness_activity": [.traditionalChinese: "使用中的 App 與作息", .english: "Apps & breaks", .japanese: "使用中のアプリと休憩", .korean: "사용 중인 앱과 휴식"],
        "awareness_media": [.traditionalChinese: "正在播放的音樂", .english: "Music playing", .japanese: "再生中の音楽", .korean: "재생 중인 음악"],
        "awareness_video": [.traditionalChinese: "YouTube・ニコニコ動画", .english: "YouTube / Niconico", .japanese: "YouTube・ニコニコ動画", .korean: "YouTube / 니코니코 동화"],
        "awareness_screen": [.traditionalChinese: "定時看看畫面", .english: "Glance at the screen", .japanese: "ときどき画面を見る", .korean: "가끔 화면 살펴보기"],
